"""core.challenges: SCEP challenges generated by the server (ADR-0019)."""

import pytest

from h42pki.core.challenges import (
    ALPHABET,
    hash_secret,
    new_challenge,
    parse_challenge,
    secret_matches,
)


def test_format() -> None:
    challenges = [new_challenge() for _ in range(50)]

    for challenge in challenges:
        assert len(challenge.text) == 41 <= 64
        assert set(challenge.text.replace("-", "")) <= set(ALPHABET)
        assert challenge.text.count("-") == 1
        assert parse_challenge(challenge.text) == challenge
    assert len({challenge.identifier for challenge in challenges}) == 50
    assert "redacted" in repr(challenges[0]) and challenges[0].secret not in repr(challenges[0])


def test_parse_tolerates_case_and_spaces() -> None:
    challenge = new_challenge()

    assert parse_challenge(f"  {challenge.text.lower()}\n") == challenge


@pytest.mark.parametrize(
    "text",
    [
        "",
        "ABCDEFGH",
        "ABCDEFGH-",
        "ABCDEFG-" + "A" * 32,
        "ABCDEFGH-" + "A" * 31,
        "ABCDEFGH_" + "A" * 32,
        "ABCDEFGH-" + "Ä" * 32,
    ],
)
def test_parse_refuses(text: str) -> None:
    assert parse_challenge(text) is None


def test_hash_and_compare() -> None:
    challenge = new_challenge()
    stored = hash_secret(challenge.secret)

    assert stored.startswith("sha256$") and challenge.secret not in stored
    assert secret_matches(challenge.secret, stored)
    assert not secret_matches(new_challenge().secret, stored)
    assert not secret_matches(challenge.secret, None)
